 <script>const offerings=@json(array_values($page['items']??[])),assetRoot=@json(url('public'));document.getElementById('shareButton').addEventListener('click',async()=>{fetch(@json(route('business.track',$business->public_slug)),{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':@json(csrf_token()),Accept:'application/json'},body:JSON.stringify({event_type:'share'}),keepalive:true}).catch(()=>{});const data={title:@json($business->cmpd_name),text:'View this business on Net-Works',url:location.href};if(navigator.share){await navigator.share(data)}else{await navigator.clipboard.writeText(location.href);const button=document.getElementById('shareButton');button.textContent='✓ Link copied';setTimeout(()=>button.textContent='↗ Share',1800)}});const productDialog=document.getElementById('productEnquiryDialog'),previewDialog=document.getElementById('productPreviewDialog'),openEnquiry=title=>{if(!productDialog)return;document.getElementById('productTitleInput').value=title;document.getElementById('productTitleText').textContent=title;document.getElementById('productMessage').value='I want to know more about this.';productDialog.showModal()};document.querySelectorAll('.product-preview').forEach(button=>button.addEventListener('click',()=>{const item=offerings[+button.dataset.itemIndex]||{};document.getElementById('previewTitle').textContent=item.title||'Offering details';document.getElementById('previewDescription').textContent=item.description||'No additional description is available.';document.getElementById('previewPrice').textContent=item.price_label||'';const image=document.getElementById('previewImage');if(item.image){image.src=assetRoot+'/'+item.image;image.alt=item.title||'Offering image';image.hidden=false}else{image.hidden=true;image.removeAttribute('src')}const whatsApp=document.getElementById('previewWhatsappAction');if(whatsApp)whatsApp.href=button.dataset.whatsappUrl||'#';const email=document.getElementById('previewEmailAction');if(email)email.dataset.product=item.title||'';previewDialog.showModal()}));document.getElementById('previewEmailAction')?.addEventListener('click',event=>{previewDialog.close();openEnquiry(event.currentTarget.dataset.product)});document.querySelectorAll('.preview-close').forEach(button=>button.addEventListener('click',()=>previewDialog.close()));document.querySelectorAll('.enquiry-close').forEach(button=>button.addEventListener('click',()=>productDialog?.close()));[previewDialog,productDialog].filter(Boolean).forEach(dialog=>dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()}))</script>
</body></html>
